<script setup lang="ts">
import ConsoleDialog from './ConsoleDialog.vue'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import {decorationIcons,decorationIconGroups,decorationIconLabels,decorationIconUrl} from '../../../../api/src/core/decoration-framework.mjs'
const props=defineProps<{label:string;imageUrl:(id:string)=>string;disabled?:boolean;fallbackIcon?:string;fallbackImage?:string}>()
const imageId=defineModel<string|null>('imageId',{required:true})
const icon=defineModel<string|undefined>('icon')
defineEmits<{pick:[]}>()
const open=ref(false),search=ref(''),category=ref('全部')
const icons=computed(()=>decorationIconGroups.filter(group=>category.value==='全部'||category.value===group.label).flatMap(group=>group.items).filter(item=>(item.value+' '+item.label).includes(search.value.trim().toLowerCase())))
const source=computed(()=>imageId.value?props.imageUrl(imageId.value):icon.value?decorationIconUrl(icon.value):props.fallbackImage||decorationIconUrl(props.fallbackIcon))
function choose(name:string){if(props.disabled||!decorationIcons.includes(name))return;icon.value=name;imageId.value=null;open.value=false}
function clear(){if(props.disabled)return;imageId.value=null;icon.value=undefined}
</script>
<template><div class="visual-picker"><span class="visual-label">{{label}}</span><div class="visual-controls"><div class="visual-preview"><img v-if="source" :src="source" :alt="label"><UIcon v-else name="i-lucide-image"/></div><div class="visual-actions"><div><UButton color="neutral" variant="outline" size="sm" icon="i-lucide-image-plus" :disabled="disabled" @click="$emit('pick')">选择图片</UButton><UButton color="neutral" variant="outline" size="sm" icon="i-lucide-layout-grid" :disabled="disabled" @click="search='';category='全部';open=true">内置图标</UButton></div><span class="visual-hint">{{imageId?'自定义图片':icon?decorationIconLabels[icon]:'使用默认图标'}}<button v-if="imageId||icon" type="button" :disabled="disabled" @click="clear">恢复默认</button></span></div></div><ConsoleDialog v-model:open="open" title="选择内置图标" size="picker"><template #body><div class="visual-dialog"><div class="visual-toolbar"><ConsoleInput v-model="search" placeholder="搜索名称，如：首页、订单、客服" aria-label="搜索内置图标"/><span>{{icons.length}} 个图标</span></div><div class="visual-categories"><button v-for="name in ['全部',...decorationIconGroups.map(g=>g.label)]" :key="name" type="button" :aria-pressed="category===name" @click="category=name">{{name}}</button></div><div class="visual-icons"><button v-for="item in icons" :key="item.value" type="button" :aria-label="item.label" :aria-pressed="!imageId&&icon===item.value" :disabled="disabled" @click="choose(item.value)"><img :src="decorationIconUrl(item.value)" alt=""><span>{{item.label}}</span></button></div><p v-if="!icons.length" class="visual-empty">没有匹配的图标</p></div></template><template #footer><div class="visual-footer"><span>点击图标即可选用</span><UButton color="neutral" variant="outline" @click="open=false">取消</UButton></div></template></ConsoleDialog></div></template>
<style scoped>
.visual-picker{display:grid;gap:10px;min-width:0}.visual-label{font-size:12px}.visual-controls{display:flex;align-items:center;gap:12px;min-width:0}.visual-preview{width:64px;height:64px;flex-shrink:0;border:1px solid var(--ui-border);border-radius:8px;background:var(--ui-bg-elevated);display:grid;place-items:center}.visual-preview img{width:36px;height:36px;object-fit:contain}.visual-preview .iconify{font-size:24px;color:var(--ui-text-dimmed)}.visual-actions{min-width:0;display:grid;gap:8px}.visual-actions>div{display:flex;gap:8px;flex-wrap:wrap}.visual-hint{font-size:11px;color:var(--ui-text-muted);display:flex;align-items:center;gap:12px;flex-wrap:wrap}.visual-hint button{color:var(--ui-primary)}.visual-dialog{padding:20px 24px}.visual-toolbar{display:flex;align-items:center;gap:16px}.visual-toolbar>:first-child{flex:1;min-width:0}.visual-toolbar>span{font-size:12px;color:var(--ui-text-muted);white-space:nowrap}.visual-categories{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.visual-categories button{padding:6px 12px;border-radius:6px;font-size:12px;color:var(--ui-text-muted)}.visual-categories button[aria-pressed=true]{color:var(--ui-primary);background:color-mix(in srgb,var(--ui-primary) 9%,var(--ui-bg))}.visual-icons{display:grid;grid-template-columns:repeat(auto-fill,minmax(76px,1fr));gap:10px}.visual-icons button{display:flex;flex-direction:column;align-items:center;gap:9px;padding:13px 5px;border:1px solid var(--ui-border);border-radius:8px;font-size:11px}.visual-icons button:hover,.visual-icons button[aria-pressed=true]{border-color:var(--ui-primary);background:var(--ui-bg-elevated)}.visual-icons img{width:26px;height:26px;object-fit:contain}.visual-empty{text-align:center;padding:48px 0;color:var(--ui-text-muted);font-size:13px}.visual-footer{display:flex;align-items:center;justify-content:space-between;width:100%;gap:16px}.visual-footer>span{font-size:12px;color:var(--ui-text-muted)}@media(max-width:600px){.visual-dialog{padding:16px}.visual-toolbar>span{display:none}}
</style>
